/**
 * Storage of categories.
 */

import { Injectable } from '@nestjs/common'
import { InjectRepository } from '@nestjs/typeorm'
import { Repository, type DeepPartial } from 'typeorm'
import { type ListQuery, type ListResult } from '../common/listing'
import { type CategoryRecord } from './category.dto'
import { CategoryEntity } from './category.entity'

/** Injection token of the storage of categories. */
export const CATEGORY_REPOSITORY = Symbol('CategoryRepository')

/** Where categories are kept. The service depends only on this interface. */
export interface CategoryRepository {
  list(query: ListQuery): Promise<ListResult<CategoryRecord>>
  get(key: number): Promise<CategoryRecord | undefined>
  add(values: Omit<CategoryRecord, 'id'>): Promise<CategoryRecord>
  update(key: number, values: Partial<CategoryRecord>): Promise<CategoryRecord>
  delete(key: number): Promise<void>
}

/** A stored row as a record: empty columns become absent fields, as the API shows optional fields. */
function toRecord(row: CategoryEntity): CategoryRecord {
  return Object.fromEntries(Object.entries(row).filter(([, value]) => value !== null)) as unknown as CategoryRecord
}

/** Keeps categories in the database with TypeORM. */
@Injectable()
export class TypeOrmCategoryRepository implements CategoryRepository {
  constructor(@InjectRepository(CategoryEntity) private readonly data: Repository<CategoryEntity>) {}

  async list(query: ListQuery): Promise<ListResult<CategoryRecord>> {
    const order = query.sort ? { [query.sort.field]: query.sort.descending ? 'DESC' : 'ASC', id: 'ASC' } : { id: 'ASC' }
    const [rows, total] = await this.data.findAndCount({
      where: query.filters as never,
      order: order as never,
      skip: query.offset,
      take: query.limit,
    })
    return { items: rows.map(toRecord), total }
  }

  async get(key: number): Promise<CategoryRecord | undefined> {
    const row = await this.data.findOneBy({ id: key } as never)
    return row ? toRecord(row) : undefined
  }

  async add(values: Omit<CategoryRecord, 'id'>): Promise<CategoryRecord> {
    const row = await this.data.save(this.data.create(values as DeepPartial<CategoryEntity>))
    return (await this.get(row.id as number))!
  }

  async update(key: number, values: Partial<CategoryRecord>): Promise<CategoryRecord> {
    const row = await this.data.findOneByOrFail({ id: key } as never)
    await this.data.save(this.data.merge(row, values as DeepPartial<CategoryEntity>))
    return (await this.get(key))!
  }

  async delete(key: number): Promise<void> {
    await this.data.delete({ id: key } as never)
  }
}

